// In the newest n8n Code Tool versions, inputs ARE passed in a global 'properties' object.
// We use this specific structure to ensure it runs.

async function execute() {
  // 1. SAFE VARIABLE EXTRACTION
  // If n8n passes them as globals (older versions), use them. 
  // If passed as 'properties' object (newer versions), use that.
  const props = (typeof properties !== 'undefined') ? properties : {};

  // Fallback check for variables if they are global
  const repoName = props.repo_name || (typeof repo_name !== 'undefined' ? repo_name : null);
  const token = props.github_token || (typeof github_token !== 'undefined' ? github_token : null);

  if (!repoName) return "Error: repo_name parameter is missing";
  if (!token) return "Error: github_token parameter is missing";

  const projectTitle = repoName;

  // 2. HELPER FUNCTIONS
  const rest = async (url, method, body) => {
    const opts = {
      method,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/vnd.github.v3+json',
        'User-Agent': 'n8n-tool'
      }
    };
    if (body) opts.body = JSON.stringify(body);
    const res = await fetch(`https://api.github.com${url}`, opts);
    if (!res.ok) throw new Error(`REST Error: ${await res.text()}`);
    return await res.json();
  };

  const gql = async (query, vars) => {
    const res = await fetch('https://api.github.com/graphql', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
        'User-Agent': 'n8n-tool'
      },
      body: JSON.stringify({ query, variables: vars })
    });
    const json = await res.json();
    if (json.errors) throw new Error(`GraphQL Error: ${JSON.stringify(json.errors)}`);
    return json.data;
  };

  try {
    // 3. EXECUTION
    // Get User ID
    const user = await gql(`query { viewer { login id } }`);
    const ownerId = user.viewer.id;
    const username = user.viewer.login;

    // Create Repo
    const repo = await rest('/user/repos', 'POST', {
      name: repoName,
      private: true,
      has_issues: true,
      has_projects: true
    });

    // Create Project
    const projData = await gql(`
      mutation($ownerId: ID!, $title: String!) {
        createProjectV2(input: { ownerId: $ownerId, title: $title }) {
          projectV2 { id url }
        }
      }
    `, { ownerId, title: projectTitle });

    const projectId = projData.createProjectV2.projectV2.id;

    // Create Issue
    const issue = await rest(`/repos/${username}/${repoName}/issues`, 'POST', {
      title: 'Setup',
      body: 'Automated setup'
    });

    // Link Issue to Project
    await gql(`
      mutation($pid: ID!, $cid: ID!) {
        addProjectV2ItemById(input: { projectId: $pid, contentId: $cid }) {
          item { id }
        }
      }
    `, { pid: projectId, cid: issue.node_id });

    // Link Repo to Project (Try/Catch as it's optional/finicky)
    try {
       await gql(`
        mutation($pid: ID!, $rid: ID!) {
          linkProjectV2ToRepository(input: { projectId: $pid, repositoryId: $rid }) {
            repository { name }
          }
        }
       `, { pid: projectId, rid: repo.node_id });
    } catch(e) {}

    return JSON.stringify({
      status: "success",
      repo: repo.html_url,
      project: projData.createProjectV2.projectV2.url
    });

  } catch (err) {
    return `Error: ${err.message}`;
  }
}

return execute();
